+func TestArchiveLookup(t *testing.T) {
+	a := &Archive{
+		Files: []File{
+			{"foo", []byte("foo data")},
+			{"bar", []byte("bar data")},
+		},
+	}
+
+	// Existing file: found
+	f, ok := a.Lookup("foo")
+	if !ok || f == nil || f.Name != "foo" || string(f.Data) != "foo data" {
+		t.Fatalf("Lookup(\"foo\"): got %v, %v", f, ok)
+	}
+
+	// Missing file: not found
+	f, ok = a.Lookup("baz")
+	if ok || f != nil {
+		t.Fatalf("Lookup(\"baz\"): got %v, %v", f, ok)
+	}
+}
